// Prototype groups use paths; production design uses stable IDs.
const groupParent=path=>path.split(' / ').slice(0,-1).join(' / ');
const isWithin=(path,root)=>path===root||path.startsWith(root+' / ');
let managedGroup=null,groupDraftNew=false,deleteRoot=null;
document.body.insertAdjacentHTML('beforeend',`<dialog id="groupManager" aria-labelledby="groupManagerTitle"><div class="dialog-head"><h2 id="groupManagerTitle">管理分组</h2><button type="button" id="closeGroupManager" aria-label="关闭分组管理">✕</button></div><div class="group-manager-body"><section class="group-list-panel"><div class="group-list-tools"><input id="manageSearch" type="search" aria-label="搜索分组" placeholder="搜索分组…"><button id="newGroup" type="button">＋ 新建</button></div><div id="manageTree" aria-label="分组列表"></div></section><form id="groupForm"><div class="dialog-body"><h2 id="groupFormTitle">选择分组</h2><p id="groupPath" class="muted"></p><label class="field">名称<input id="groupName" maxlength="40" required autocomplete="off"></label><label class="field">父分组<select id="groupParent"></select></label><p class="muted">修改父分组可移动整个分组及其子分组。</p><p id="groupImpact" class="muted"></p><p id="groupError" role="alert" class="error"></p></div><div class="dialog-footer"><button id="deleteGroup" type="button" class="error">删除分组</button><button type="submit" id="saveGroup" class="primary">保存</button></div></form></div></dialog><dialog id="deleteGroupDialog" aria-labelledby="deleteGroupTitle"><div class="dialog-head"><h2 id="deleteGroupTitle">删除分组</h2><button type="button" id="closeDeleteGroup" aria-label="关闭删除确认">✕</button></div><div class="dialog-body"><p id="deleteGroupImpact"></p><label class="field" style="margin-top:16px">卡片迁移到<select id="deleteDestination"></select></label><p class="muted">所选分组及全部子分组将被删除，卡片保留并统一迁移到指定位置。运行记录不受影响。</p></div><div class="dialog-footer"><button id="cancelDeleteGroup" type="button">取消</button><button id="confirmDeleteGroup" type="button" class="primary">迁移并删除</button></div></dialog>`);
for(const id of ['groupPicker','editPicker']){const button=document.createElement('button');button.type='button';button.className='manage-groups-entry';button.textContent='管理分组';button.onclick=()=>{closePicker(id);openGroupManager()};$(id).querySelector('.tree-popup').append(button)}
function groupOptionsFor(excluded,emptyLabel){return `<option value="">${emptyLabel}</option>`+groups.filter(g=>!excluded||!isWithin(g,excluded)).map(g=>`<option value="${esc(g)}">${esc(g)}</option>`).join('')}
function renderManageTree(){const q=$('manageSearch').value.trim().toLowerCase();const matches=groups.filter(g=>g.toLowerCase().includes(q));const visible=groups.filter(g=>!q||matches.some(m=>isWithin(m,g)));$('manageTree').innerHTML=visible.map(g=>`<button type="button" data-manage-group="${esc(g)}" aria-pressed="${managedGroup===g&&!groupDraftNew}" style="padding-left:${10+(g.split(' / ').length-1)*14}px" title="${esc(g)}"><span>${esc(g.split(' / ').at(-1))}</span><small>${items.filter(x=>isWithin(x.group,g)).length}</small></button>`).join('')||'<p class="muted" style="padding:12px">没有匹配的分组</p>'}
function editManagedGroup(g){managedGroup=g;groupDraftNew=false;renderManageTree();$('groupFormTitle').textContent='编辑分组';$('groupPath').textContent=g;$('groupName').value=g.split(' / ').at(-1);$('groupParent').innerHTML=groupOptionsFor(g,'顶层分组');$('groupParent').value=groupParent(g);$('deleteGroup').disabled=false;$('saveGroup').disabled=false;$('groupName').disabled=false;$('groupParent').disabled=false;$('groupError').textContent='';$('groupImpact').textContent=`${groups.filter(x=>x!==g&&isWithin(x,g)).length} 个子分组 · ${items.filter(x=>isWithin(x.group,g)).length} 张卡片`}
function newManagedGroup(){const parent=managedGroup||'';groupDraftNew=true;managedGroup=null;renderManageTree();$('groupFormTitle').textContent='新建分组';$('groupPath').textContent='';$('groupName').value='';$('groupParent').innerHTML=groupOptionsFor(null,'顶层分组');$('groupParent').value=parent;$('deleteGroup').disabled=true;$('saveGroup').disabled=false;$('groupName').disabled=false;$('groupParent').disabled=false;$('groupError').textContent='';$('groupImpact').textContent='';$('groupName').focus()}
function openGroupManager(){$('manageSearch').value='';if(groups.length)editManagedGroup(groups.includes(chosen)?chosen:groups[0]);else newManagedGroup();$('groupManager').showModal()}
function syncGroups(mapPath){for(const x of items)x.group=mapPath(x.group);chosen=chosen==='*'?'*':mapPath(chosen);for(const id of Object.keys(pickerValues)){const value=pickerValues[id];expanded[id]=new Set(groups);updatePicker(id,value==='*'?'*':mapPath(value))}selectGroup(chosen);if(selected)detail();renderManageTree()}
$('manageSearch').oninput=renderManageTree;$('newGroup').onclick=newManagedGroup;$('closeGroupManager').onclick=()=>$('groupManager').close();
$('manageTree').onclick=e=>{const b=e.target.closest('[data-manage-group]');if(b)editManagedGroup(b.dataset.manageGroup)};
$('groupForm').onsubmit=e=>{e.preventDefault();const name=$('groupName').value.trim(),parent=$('groupParent').value,old=groupDraftNew?null:managedGroup;const fail=m=>$('groupError').textContent=m;if(!name||name.length>40)return fail('名称需为 1–40 个字符。');if(name.includes('/'))return fail('名称不能包含斜杠，请通过父分组设置层级。');if(parent&&!groups.includes(parent))return fail('父分组不存在，请重新选择。');if(old&&parent&&isWithin(parent,old))return fail('不能移动到自身或子分组。');const next=parent?parent+' / '+name:name;if(groups.some(g=>g===next&&g!==old))return fail('同一父分组下已有此名称。');const subtree=old?groups.filter(g=>isWithin(g,old)):[name];const extra=old?Math.max(...subtree.map(g=>g.split(' / ').length-old.split(' / ').length)):0;if(next.split(' / ').length+extra>5)return fail('分组最多支持 5 层，请选择更上层的父分组。');if(!old)groups.push(next);else for(let i=0;i<groups.length;i++)if(isWithin(groups[i],old))groups[i]=next+groups[i].slice(old.length);groups.sort((a,b)=>a.localeCompare(b,'zh-CN'));syncGroups(g=>old&&isWithin(g,old)?next+g.slice(old.length):g);editManagedGroup(next);toast(old?'分组已更新':'分组已创建')};
$('deleteGroup').onclick=()=>{deleteRoot=managedGroup;const descendants=groups.filter(g=>g!==deleteRoot&&isWithin(g,deleteRoot)).length,cards=items.filter(x=>isWithin(x.group,deleteRoot)).length;$('deleteGroupImpact').textContent=`删除“${deleteRoot}”及 ${descendants} 个子分组，将迁移 ${cards} 张卡片。`;$('deleteDestination').innerHTML=groupOptionsFor(deleteRoot,'未分组');$('deleteGroupDialog').showModal()};
for(const id of ['closeDeleteGroup','cancelDeleteGroup'])$(id).onclick=()=>$('deleteGroupDialog').close();
$('confirmDeleteGroup').onclick=()=>{const root=deleteRoot,dest=$('deleteDestination').value;if(!groups.includes(root)||dest&&(!groups.includes(dest)||isWithin(dest,root)))return;for(let i=groups.length-1;i>=0;i--)if(isWithin(groups[i],root))groups.splice(i,1);syncGroups(g=>isWithin(g,root)?dest:g);$('deleteGroupDialog').close();managedGroup=null;if(groups.length)editManagedGroup(groups.includes(dest)?dest:groups[0]);else newManagedGroup();toast('分组已删除，卡片已迁移')};
